from taf.gnb.oam.coam.vdu import vdu
from taf.config.testline.gnb.du import DU, VDU
from taf.gnb.oam.coam.vdu.exceptions import M2MInterfaceDisabled

from .bts import Bts


class BtsCloudDu(Bts):
    """ Represents API to DU part of gNB BTS with Cloud topology. """

    def __init__(self):
        super(BtsCloudDu, self).__init__()
        self._api = vdu()

    def _connect_to(self, config, name, log_dir, timeout, **kwargs):
        du_id = int(kwargs.get('du_id', 0))
        bts_port = 443
        username = 'Nemuadmin'
        password = 'nemuuser'

        if config and isinstance(config.dus[du_id], DU) and config.dus[du_id].oam_ip:
            self._host = config.dus[du_id].oam_ip.v4.split('/')[0]
        elif config and isinstance(config.dus[du_id], VDU) and config.dus[du_id].oam_http_connection_details:
            self._host = config.dus[du_id].oam_http_connection_details.addr
            bts_port = config.dus[du_id].oam_http_connection_details.port
            username = config.dus[du_id].oam_http_connection_details.username
            password = config.dus[du_id].oam_http_connection_details.password
        else:
            self._host = '192.168.255.129'

        self._logger.info(self._CONNECTION_LOG_MSG.format('gNB Cloud DU', self._host, bts_port, username, password))

        self._api.connect_to(host=self._host,
                             port=bts_port,
                             username=username,
                             password=password,
                             secure=True,
                             connection_name=name,
                             timeout=timeout)

    def _get_active_alarms(self, connection, timeout):
        try:
            return self._api.vdu_get_active_alarms(vdu_connection=connection, timeout=timeout)['alarms']
        except M2MInterfaceDisabled:
            return self._api.vdu_get_active_alarms(vdu_connection=connection, timeout=timeout, use_m2m=False)['alarms']

    def _disconnect(self, connection):
        self._api.disconnect(vdu_connection=connection)
